				.forRecordStreamFormat(new TextLineFormat(), Path.fromLocalFile(testDir))
				.monitorContinuously(Duration.ofMillis(5))
				.build();

		final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
